Review this Express code for security problems.

```ts
import { Router } from "express";
import { pool } from "./db";
import { requireUser } from "./auth";

export const router = Router();

router.get("/saker", requireUser, async (req, res) => {
  const status = String(req.query.status ?? "open");
  const sort = String(req.query.sort ?? "created_at");
  const result = await pool.query(
    `SELECT id, title, status, created_at FROM saker
     WHERE kommune_id = $1 AND status = $2
     ORDER BY ${sort} DESC LIMIT 50`,
    [req.user.kommuneId, status],
  );
  res.json(result.rows);
});

router.get("/saker/:id", requireUser, async (req, res) => {
  const result = await pool.query(
    "SELECT id, title, status, created_at FROM saker WHERE id = $1 AND kommune_id = $2",
    [req.params.id, req.user.kommuneId],
  );
  if (result.rowCount === 0) return res.sendStatus(404);
  res.json(result.rows[0]);
});
```

Review this Spring controller for security problems.

```java
@RestController
@RequestMapping("/api/rapporter")
class RapportController {
    enum Sortering { OPPRETTET, TITTEL }

    private final JdbcTemplate jdbc;
    private final RapportRepository repo;

    RapportController(JdbcTemplate jdbc, RapportRepository repo) {
        this.jdbc = jdbc;
        this.repo = repo;
    }

    @GetMapping
    List<RapportDto> liste(@RequestParam(defaultValue = "OPPRETTET") Sortering sortering, Authentication auth) {
        String kolonne = switch (sortering) {
            case OPPRETTET -> "opprettet";
            case TITTEL -> "tittel";
        };
        return jdbc.query(
            "SELECT id, tittel, opprettet FROM rapport WHERE kommune_id = ? ORDER BY " + kolonne,
            RapportDto.MAPPER, Tilgang.kommuneId(auth));
    }

    @GetMapping("/{id}/pdf")
    @PreAuthorize("@tilgang.kanLese(authentication, #id)")
    ResponseEntity<byte[]> pdf(@PathVariable UUID id) throws NoSuchAlgorithmException {
        byte[] body = repo.findById(id)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND))
            .pdf();
        String etag = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(body));
        return ResponseEntity.ok().eTag(etag).contentType(MediaType.APPLICATION_PDF).body(body);
    }
}
```

