[ApiController]
[Route("api/meldinger")]
public class MeldingController : ControllerBase
{
    private static readonly JsonSerializerSettings Settings = new() { TypeNameHandling = TypeNameHandling.Auto };
    private readonly IDbConnection _db;
    private readonly ILogger<MeldingController> _log;

    public MeldingController(IDbConnection db, ILogger<MeldingController> log)
    {
        _db = db;
        _log = log;
    }

    [HttpPost]
    [Authorize]
    public async Task<IActionResult> Opprett()
    {
        using var reader = new StreamReader(Request.Body);
        var json = await reader.ReadToEndAsync();
        var melding = JsonConvert.DeserializeObject<Melding>(json, Settings);
        _log.LogInformation("Ny melding: {Melding}", json);
        await _db.ExecuteAsync(
            "INSERT INTO melding (avsender_fnr, tekst) VALUES (@AvsenderFnr, @Tekst)", melding);
        return Ok();
    }
}

public class Melding
{
    public string AvsenderFnr { get; set; } = "";
    public string Tekst { get; set; } = "";
    public object? Vedlegg { get; set; }
}
