Vi skal brukerteste dette skjemaet med tre skjermleserbrukere på torsdag. Er det klart for testen?

```tsx
export function SkyssSoknad({ onSend }: { onSend: (data: Skjema) => Promise<void> }) {
  const [fodselsdato, setFodselsdato] = useState("");
  const [skole, setSkole] = useState("");
  const [avstand, setAvstand] = useState<"under4" | "over4" | "">("");
  const [feil, setFeil] = useState<string | null>(null);

  async function send() {
    if (!/^\d{2}\.\d{2}\.\d{4}$/.test(fodselsdato)) {
      setFeil("Ugyldig dato");
      return;
    }
    await onSend({ fodselsdato, skole, avstand });
  }

  return (
    <div className="side">
      <div className="tittel">Søknad om skoleskyss</div>
      <input
        placeholder="Fødselsdato (dd.mm.åååå)"
        value={fodselsdato}
        onChange={(e) => setFodselsdato(e.target.value)}
      />
      {feil && <span className="feil">{feil}</span>}
      <label htmlFor="skole">Skole</label>
      <input id="skole" value={skole} onChange={(e) => setSkole(e.target.value)} />
      <fieldset>
        <legend>Hvor langt er skoleveien?</legend>
        <label>
          <input type="radio" name="avstand" checked={avstand === "under4"} onChange={() => setAvstand("under4")} />
          Under 4 km
        </label>
        <label>
          <input type="radio" name="avstand" checked={avstand === "over4"} onChange={() => setAvstand("over4")} />
          4 km eller mer
        </label>
      </fieldset>
      <div className="knapp" onClick={send}>Send søknad</div>
      <button className="lukk" onClick={() => history.back()}>
        <img src="/ikoner/kryss.svg" />
      </button>
    </div>
  );
}
```

