Neste uke tester vi avbestilling av timer med to personer som bare bruker tastatur, og én som forstørrer skjermen kraftig. Er denne delen klar?

```tsx
export function Timeliste({ timer, avbestill }: { timer: Time[]; avbestill: (id: string) => Promise<void> }) {
  const [valgt, setValgt] = useState<Time | null>(null);
  const [melding, setMelding] = useState("");

  async function bekreft() {
    await avbestill(valgt!.id);
    setValgt(null);
    setMelding("Timen er avbestilt");
    setTimeout(() => setMelding(""), 3000);
  }

  return (
    <main>
      <h1>Dine timer</h1>
      <ul>
        {timer.map((t) => (
          <li key={t.id}>
            {t.dato} kl. {t.klokkeslett}
            <button onClick={() => setValgt(t)}>Avbestill</button>
          </li>
        ))}
      </ul>
      {valgt && (
        <div className="overlegg">
          <div className="dialog">
            <p>Vil du avbestille timen {valgt.dato}?</p>
            <button onClick={bekreft}>Ja, avbestill</button>
            <button onClick={() => setValgt(null)}>Nei</button>
          </div>
        </div>
      )}
      {melding && <div className="toast">{melding}</div>}
    </main>
  );
}
```

